scription": "正统十一年九月辛巳，广西瑶民中有人起事，俘获化州知州茅自得，杀死千户汪义。", "start_year": 1446, "end_year": 1446, "time_original": "正统十一年九月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ffbd489b-e8ed-5aa1-9c7e-4fe15e0ed787"}, {"title": "明廷派给事中和御史分赴各边镇赏赐军士", "description": "正统十一年十月甲寅，朝廷派给事中和御史分赴各处边镇，赏赐当地军士。", "start_year": 1446, "end_year": 1446, "time_original": "正统十一年十月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "81df6943-33d9-5eaf-9cf5-e7bbbb1ddcde"}, {"title": "明廷减免死罪及以下的刑罚", "description": "正统十一年十一月壬申，朝廷对判处死罪及以下罪行的刑罚予以减等。", "start_year": 1446, "end_year": 1446, "time_original": "正统十一年十一月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5ce93ae1-4f63-5948-ad1d-6e4a77835e02"}, {"title": "本纪汇记正统十一年多地入贡", "description": "正统十一年，琉球中山、暹罗、安南、爪哇、回回哈密、占城、亦力把里、撒马儿罕和乌斯藏入贡。 按原历纪年，事情发生在公元1446至1447年之间。", "start_year": null, "end_year": null, "time_original": "正统十一年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "409d396a-97c9-5461-b653-63451d9ba99a"}, {"title": "明英宗在南郊祭祀天地", "description": "正统十二年正月癸酉，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年正月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "efa33c3a-7ca7-5459-bf66-2f1cd86a21ea"}, {"title": "明英宗前往天寿山", "description": "正统十二年三月癸亥，明英宗朱祁镇前往天寿山。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年三月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f729ec5e-50f9-5ded-a007-2f84ad491b38"}, {"title": "明英宗返回宫中", "description": "正统十二年三月庚午，明英宗朱祁镇返回宫中。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年三月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2c3ba17e-0f10-597a-8e5a-914193944fce"}, {"title": "明廷豁免杭、嘉、湖灾区秋粮", "description": "正统十二年三月丙子，朝廷免除杭州、嘉兴、湖州灾区应缴的秋粮。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年三月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3836583e-9b7d-5b86-8c36-85ec14d66fb9"}, {"title": "明廷减免苏松常镇灾区秋粮", "description": "正统十二年四月丁巳，朝廷免除苏州、松江、常州、镇江受灾地区所涉秋粮。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年四月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f2d9262-fc0c-5b30-a86b-0905bd31d3ef"}, {"title": "张骥奉命救济济宁和淮扬饥民", "description": "正统十二年五月己亥，大理少卿张骥奉命赈济济宁以及淮安、扬州的饥民。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年五月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "286cb527-fecb-5ab8-ac65-2da6930ae72e"}, {"title": "明廷命各边镇操练军队，防备瓦剌", "description": "正统十二年七月甲辰，朝廷命各边镇操练军队，防备瓦剌。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年七月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8104076b-4855-5618-b96a-85f6871ea78e"}, {"title": "本纪记八月初一日食", "description": "正统十二年八月初一，发生日食。", "start_year": 1447, "end_year": 1447, "time_original": "正统十二年八月庚申朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "49cb922c-e34d-5f00-bfd3-fe798907382b"}, {"title": "马愉去世", "description": "正統12年（1447年）九月，马愉去世。", "start_year": 1447, "end_year": 1447, "time_original": "正統12年（1447年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6de8c995-e3c1-50fa-9458-11d76395439b"}, {"title": "本纪汇记正统十二年多地入贡", "description": "正统十二年，琉球中山、安南、占城、瓦剌、爪哇、哈密和暹罗入贡。 按原历纪年，事情发生在公元1447至1448年之间。", "start_year": null, "end_year": null, "time_original": "正统十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7199016c-d3f6-5c15-bd8c-860ab36fbfab"}, {"title": "明英宗在南郊祭祀天地", "description": "正统十三年正月丁酉，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年正月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "22c1fed1-44df-5727-b842-44f16ccd18ad"}, {"title": "明廷下诏要求孟养宣慰司交出思机发", "description": "正统十三年三月戊子，朝廷下诏，要求孟养宣慰司交出思机发。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年三月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33fe02a4-b230-50a6-8d88-655bbfd8563d"}, {"title": "明廷授予彭时等人进士资格", "description": "正统十三年三月壬寅，朝廷给彭时等人授予不同等第的进士资格。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年三月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8ffaf87f-6fba-550e-8467-634d962d2bb4"}, {"title": "明廷再派部队征讨思机发，王骥总督军务", "description": "正统十三年三月，朝廷命王骥继续总督军务，任命都督同知宫聚为平蛮将军、总兵官，率兵征讨思机发。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6bdce48-f5e9-58d5-9981-17ad34614e64"}, {"title": "明廷豁免浙赣及湖广灾区秋粮", "description": "正统十三年四月，朝廷豁免浙江、江西、湖广受灾地区应缴的秋粮。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "27e3a7a3-6b86-5098-80c7-04b856f2e0c1"}, {"title": "明廷派使者到山东组织捕蝗", "description": "正统十三年五月丙戌，朝廷派人到山东组织捕蝗。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年五月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4d43e64b-ace8-59d6-ad9f-a561b2d22705"}, {"title": "丁铉奉命安抚河南和山东灾民", "description": "正统十三年五月甲辰，刑部侍郎丁铉奉命安抚河南和山东的灾民。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年五月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "43f5c9f9-5c67-518c-974c-4d752b86bd6b"}, {"title": "黄河在大名决口，明廷派人减免赋税并赈济", "description": "正统十三年七月乙酉，黄河在大名决口。本纪记受淹范围三百余里，朝廷派使者前往减税赈灾。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年七月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "683300e0-5f8a-572c-ad80-3b9533edacb8"}, {"title": "黄河在河南决口并毁坏运道，王永和奉命治理", "description": "正统十三年七月己酉，黄河在河南决口，水淹曹、濮、东昌等地。寿张沙湾也发生溃决，运道受损，工部侍郎王永和奉命治理。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年七月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "77b338a5-c2ae-5dc4-8e77-0194af7fc074"}, {"title": "邓茂七在福建起事", "description": "正统十三年八月乙卯，邓茂七在福建起事，反抗明廷。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年八月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f420a409-a2ae-56d1-829f-5816b771d3e0"}, {"title": "明廷派御史丁瑄查捕邓茂七", "description": "正统十三年八月甲戌，朝廷命御史丁瑄查捕在福建起事的邓茂七。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年八月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "905cd20c-f07d-5f1b-9f1c-3ee870d6c6e5"}, {"title": "陈懋奉命率军征讨邓茂七，金濂参赞", "description": "正统十三年十一月丙戌，朝廷任命宁阳侯陈懋为总兵官、梁珤和陈豫为副手，命曹吉祥、王瑾掌管军中火器，刑部尚书金濂参赞，率兵征讨邓茂七。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年十一月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7682399e-470c-569c-a698-eeb5f779cf6b"}, {"title": "处州一带武装袭扰金华各县", "description": "正统十三年十一月甲辰，《明史》本纪记来自处州的武装袭扰金华各县。", "start_year": 1448, "end_year": 1448, "time_original": "正统十三年十一月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0b0af0d-4a16-559e-a629-117704718f2e"}, {"title": "徐安奉命在山东防御倭寇", "description": "正统十三年十一月庚戌，明廷派永康侯徐安在山东防御倭寇。", "start_year": 1449, "end_year": 1449, "time_original": "正统十三年十一月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28db7031-f42f-5cf5-bfc2-850efbdbd448"}, {"title": "本纪记广东瑶民中有人反抗明廷", "description": "正统十三年十二月庚午，本纪记广东瑶民中有人起事，反抗明廷。", "start_year": 1449, "end_year": 1449, "time_original": "正统十三年十二月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eaae2fb6-3750-5460-8cbc-35250f4325aa"}, {"title": "琉球中山、安南和占城入贡", "description": "正统十三年，琉球中山、安南和占城入贡。 按原历纪年，事情发生在公元1448至1449年之间。", "start_year": null, "end_year": null, "time_original": "正统十三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "747aeba9-780e-5704-a84e-ba8c9c0aaf7a"}, {"title": "本纪记明廷赏赐瓦剌贡使不足旧例，双方出现嫌隙", "description": "正统十三年，《明史》本纪记瓦剌贡使有三千人，明廷赏赐比旧例少，并将此列作双方产生嫌隙的缘由。 按原历纪年，事情发生在公元1448至1449年之间。", "start_year": null, "end_year": null, "time_original": "正统十三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "105d8cd1-7317-5407-9b43-aa174ab7d75f"}]'::jsonb)
