INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "朱祁镇主持祭祀。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001553；正统十一年正月己卯", "note": "原文：十一年春正月己卯，大祀天地於南郊；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "3008bc01-6c49-5b99-9f33-caf1e91852b1", "subject_id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf", "source_id": "48d419c8-baa0-5e32-b6c3-355b06ae3f8e"}, {"subject_table": "event", "field_path": "description", "claim_text": "正统十一年正月己卯，明英宗朱祁镇在南郊举行祭祀天地的大典。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001553；正统十一年正月己卯", "note": "原文：十一年春正月己卯，大祀天地於南郊；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "12ce940d-7ad1-5795-be29-80e7085af838", "subject_id": "74ac6f7f-6b1d-5602-8da4-4a1f5d84c81a", "source_id": "48d419c8-baa0-5e32-b6c3-355b06ae3f8e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历正统十一年正月己卯。DDBC历表换算所据为1446-02-15至1446-02-15，据此核对公元发生年份。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001553；正统十一年正月己卯", "note": "原文：十一年春正月己卯，大祀天地於南郊；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "73e73801-4029-5927-afc0-52a96b05bb0b", "subject_id": "74ac6f7f-6b1d-5602-8da4-4a1f5d84c81a", "source_id": "48d419c8-baa0-5e32-b6c3-355b06ae3f8e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "主持祭祀", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001553；正统十一年正月己卯", "note": "原文：十一年春正月己卯，大祀天地於南郊；核对说明：只采用本段明确参与者和行动角色，既有连接按稳定编号复用。", "status": "draft", "id": "b88b5ad3-fa3c-5b07-94a1-ea42e40c4ebb", "subject_id": "7d1d64f7-7621-5322-b96e-4da4a0dd1739", "source_id": "48d419c8-baa0-5e32-b6c3-355b06ae3f8e"}, {"subject_table": "person", "field_path": "description", "claim_text": "王振弟侄获得锦衣卫世袭官职。", "citation": "《明史》卷10·本纪第十·英宗前纪·mingshi-2f603db3d81e-p001553；正统十一年正月庚辰", "note": "原文：庚辰，予太監王振等弟姪世襲錦衣衞官；核对说明：按该段身份、官职、人